H('56.d.6.C',4,"Researchers compare regions with similar climates because:","Varieties that thrive there may do well locally",["Weather is irrelevant","Soil never matters","All grapes grow everywhere"],"Similar conditions favor similar varieties.")
H('56.d.6.D',3,"A vineyard design plan should include:","Row spacing, orientation, and irrigation layout",["Menu items","Party details","Staff birthdays"],"Layout affects efficiency.")
H('56.d.6.D',4,"Rows running north to south often help by:","Giving even sunlight on both sides of the canopy",["Blocking sun","Raising frost","Reducing air flow"],"Orientation balances light.")

H('56.d.7.A',3,"Cold injury to plants occurs when temperatures:","Drop low enough to damage tissue",["Stay mild","Rise too high","Stay constant"],"Freezing damages cells.")
H('56.d.7.A',4,"Winter injury risk is greatest after:","A sudden hard freeze following mild weather",["Steady cold","Heavy irrigation","A cloudy day"],"Vines lose hardiness during warm spells.")
H('56.d.7.B',3,"Blackened, shriveled shoots after a spring freeze are signs of:","Frost damage",["Healthy growth","Overwatering","Nutrient surplus"],"Frozen tissue turns dark.")
H('56.d.7.B',4,"One way to reduce frost damage is to:","Use wind machines to mix warmer air downward",["Do nothing","Water less","Prune early only"],"Mixing air raises canopy temperature.")
H('56.d.7.C',3,"A radiation frost happens on:","Calm, clear nights when heat escapes to the sky",["Windy cloudy days","Hot afternoons","Rainy mornings"],"Radiation frosts form near the ground.")
H('56.d.7.C',4,"An advection frost is caused by:","A mass of cold air moving in with wind",["Still clear skies","Warm fog","Heat waves"],"Advection frosts bring cold air in.")
H('56.d.7.D',3,"A passive frost protection technique is:","Choosing late-budding varieties or a good site",["Burning heaters","Running fans","Using sprinklers"],"Passive methods avoid frost risk without energy input.")
