H('57.d.6.D',3,"A good consultation question is:","What is the occasion, budget, and color preference?",["Do you like flowers?","Who are you?","Why are you here?"],"Specific questions guide design.")
H('57.d.6.D',4,"Listening carefully to a client's expectations helps a designer to:","Create a design that meets their vision",["Ignore wishes","Charge more","Delay the order"],"Understanding needs prevents mismatches.")

H('57.d.7.A',3,"A cascade bouquet is a term used for:","Weddings",["Funerals only","Birthdays only","Graduations only"],"Cascade bouquets are bridal.")
H('57.d.7.A',4,"A casket spray is a design term used for:","Funerals",["Weddings","Proms","Holidays"],"Sprays are sympathy pieces.")
H('57.d.7.B',3,"Applying balance and proportion to a wedding bouquet means:","Sizing it to the bride and gown",["Making it huge always","Ignoring the dress","Using one flower"],"Design fits the person.")
H('57.d.7.B',4,"For a funeral wreath, a designer applies the principles by:","Creating a balanced, respectful, symmetrical form",["Using random colors","Ignoring tradition","Making it tiny"],"Respectful design suits the occasion.")
H('57.d.7.C',3,"A current floral trend is use of:","Dried and preserved materials",["Only plastic","Only candy","No flowers"],"Preserved materials are popular.")
H('57.d.7.C',4,"Sustainable floral designs trend toward:","Foam-free mechanics and locally grown stems",["More foam","Imported only","Less planning"],"Eco-friendly options are growing.")
H('57.d.7.D',3,"Floral tools should be maintained by:","Cleaning, sharpening, and storing them properly",["Leaving them dirty","Throwing them away","Sharing without cleaning"],"Maintenance extends life.")
H('57.d.7.D',4,"Rust on shears can be prevented by:","Drying and oiling the blades after use",["Soaking in water","Leaving wet","Storing outdoors"],"Dry, oiled tools resist rust.")
H('57.d.7.E',3,"An occasion-specific design for a graduation might use:","The school colors",["Random colors","Black only","No flowers"],"Colors reflect the event.")
H('57.d.7.E',4,"Designing for a memorial service differs from a celebration in that it uses:","Subdued tones and respectful forms",["Neon colors","Balloons","Party hats"],"Tone matches occasion.")

H('57.d.8.A',3,"During a consultation, a designer gathers details such as:","Occasion, venue, budget, and color palette",["Shoe size","Phone brand","Favorite TV"],"These details shape the proposal.")
H('57.d.8.A',4,"Visiting the event venue before designing helps to:","See the space, lighting, and logistics",["Skip planning","Delay the order","Reduce quality"],"Venue details affect design.")
H('57.d.8.B',3,"A designer selects arrangements that:","Meet the client's objectives and budget",["Ignore the budget","Cost the most","Use the rarest flowers"],"Selection balances goals and costs.")
H('57.d.8.B',4,"If the client's budget is tight, a designer can:","Use seasonal blooms and fewer focal flowers",["Refuse the job","Use only wilted stems","Ignore the budget"],"Creative choices fit budgets.")
H('57.d.8.C',3,"A floral proposal typically includes:","Design concepts, pricing, and timeline",["Only a logo","A joke","Nothing"],"Proposals set expectations.")
H('57.d.8.C',4,"Showing photos or mock-ups in a proposal helps clients to:","Visualize the finished designs",["Get confused","Skip decisions","Delay approval"],"Visuals clarify ideas.")
H('57.d.8.D',3,"A production schedule works backward from the:","Event date",["Order date","Clock time","Menu"],"Backward planning ensures readiness.")
H('57.d.8.D',4,"Allowing extra time to condition flowers in the schedule helps ensure:","Blooms open properly and last",["Wilting","Late delivery","Higher cost"],"Hydration time improves quality.")
H('57.d.8.E',3,"A procurement plan identifies:","What to buy, from whom, and when",["Only prices","Only brands","Only colors"],"Procurement ensures supplies arrive.")
H('57.d.8.E',4,"Ordering specialty flowers early is wise because they:","May have limited availability",["Are always cheap","Never run out","Have unlimited supply"],"Planning prevents shortages.")
H('57.d.8.F',3,"After completing an event, a designer should:","Evaluate results and gather feedback",["Ignore the client","Skip review","Discard notes"],"Evaluation drives improvement.")
H('57.d.8.F',4,"Comparing planned costs to actual costs after an event shows:","Where estimates were off",["Nothing","Color mistakes","Weather"],"Review improves future pricing.")

H('57.d.9.A',3,"A florist buys stems for $2 and uses a 3x markup. What is the retail price?","$6",["$5","$3","$8"],"2 times 3 equals 6.")
H('57.d.9.A',4,"A design costs $30 in materials and $20 in labor. With a 50 percent markup on total cost, the price is:","$75",["$50","$65","$100"],"Total cost 50, plus half of 50 equals 75.")
H('57.d.9.B',3,"A pricing policy is profitable if the price covers:","All costs plus profit",["Only materials","Only labor","Nothing"],"Price must exceed cost.")
H('57.d.9.B',4,"If discounts cause a design to sell below cost, the shop:","Loses money on that sale",["Gains profit","Breaks even always","Saves overhead"],"Selling below cost reduces profit.")
H('57.d.9.C',3,"A floral service contract should state:","Services, price, dates, and payment terms",["Only a handshake","Nothing","Only colors"],"Clear terms prevent disputes.")
H('57.d.9.C',4,"A deposit in a wedding contract is used to:","Secure the date and cover initial costs",["Pay taxes only","Replace payment","Cancel the order"],"Deposits reduce risk.")
H('57.d.9.D',3,"A floral budget should list the cost of:","Each item, including labor and supplies",["Only flowers","Only vases","Nothing"],"Per-item totals show true cost.")
H('57.d.9.D',4,"If a bouquet uses 12 stems at $1.50 each, the stem cost is:","$18",["$12","$15","$24"],"12 times 1.5 equals 18.")
H('57.d.9.E',3,"Good customer service in a flower shop includes:","Listening and following through on commitments",["Interrupting","Ignoring requests","Being late"],"Service builds loyalty.")
H('57.d.9.E',4,"When a customer is unhappy with a delivery, the florist should:","Apologize and offer a fair fix",["Argue","Blame them","Ignore"],"Handling complaints well keeps clients.")
H('57.d.9.F',3,"Building relationships with several growers helps a florist to:","Have backup sources and better prices",["Rely on one source","Lose options","Avoid quality"],"Variety of suppliers reduces risk.")
H('57.d.9.F',4,"A long-term vendor relationship can lead to:","Reliable supply and possible discounts",["Higher risk","Delays","Fewer choices"],"Trust benefits both sides.")
H('57.d.9.G',3,"The four Ps of marketing include product, price, place, and:","Promotion",["Plants","Pots","Pruning"],"Promotion is the fourth P.")
H('57.d.9.G',4,"Targeting brides through bridal shows is an example of:","Reaching a specific market",["Random advertising","Ignoring customers","Reducing sales"],"Target marketing focuses effort.")

H('57.d.10.A',3,"A professional organization in the floral industry is:","The American Institute of Floral Designers",["A sports league","A bank","A car club"],"AIFD is a design organization.")
H('57.d.10.A',4,"Industry organizations offer members:","Education, networking, and certification",["Free flowers","Tax cuts","Housing"],"They support professional growth.")
H('57.d.10.B',3,"A benefit of joining a floral association is:","Networking with other professionals",["No benefit","Fewer clients","Isolation"],"Contacts lead to opportunities.")
H('57.d.10.B',4,"Attending industry workshops helps designers to:","Learn new techniques and trends",["Forget skills","Avoid learning","Lose clients"],"Continuing education keeps skills current.")

# ---------------- 127.58 Principles of Plant and Soil Science ----------------
H('58.d.1.A',2,"A plant and soil science student could consider a career as:","Agronomist, soil scientist, or crop consultant",["Dancer only","Poet only","Referee only"],"Plant and soil careers involve crops and land.")
H('58.d.1.A',3,"A student exploring the field should research:","Education needs and job outlook for each role",["Only salaries of unrelated jobs","Weather","Fast food menus"],"Information guides planning.")
H('58.d.1.B',2,"Which shows professionalism in a soil testing lab?","Following procedures and labeling samples correctly",["Skipping labels","Mixing samples","Rushing and guessing"],"Careful work builds trust.")
H('58.d.1.B',3,"A technician finds a possible sample mix-up. The professional response is to:","Report it and redo the test",["Ignore it","Delete the data","Guess the result"],"Honesty protects data quality.")
H('58.d.1.C',2,"Why wear goggles and gloves when handling soil chemicals?","To protect eyes and skin",["To look serious","To keep soil clean","To save time"],"Lab chemicals can injure.")
H('58.d.1.C',3,"A safe practice in a crop field is to:","Use sun protection and drink water",["Skip water","Ignore heat","Wear no shoes"],"Field safety prevents illness.")
H('58.d.1.D',3,"Rights and responsibilities on a farm job include:","A safe workplace and following safety rules",["Ignoring rules","Hiding injuries","Skipping training"],"Both employers and employees share duties.")
H('58.d.1.D',4,"Honest reporting of test data is an example of:","Ethical conduct in science and agriculture",["Cheating","Wasting time","Ignoring rules"],"Ethics demand accuracy.")
H('58.d.1.E',2,"Good citizenship in the plant and soil field includes:","Protecting soil and water in the community",["Wasting water","Dumping waste","Ignoring erosion"],"Stewardship benefits all.")
H('58.d.1.E',3,"A citizen-minded landowner helps prevent erosion by:","Keeping ground covered with plants or mulch",["Leaving bare ground","Removing all plants","Plowing slopes downhill"],"Cover protects soil.")
H('58.d.2.A',2,"A student notices a crop wilting in one part of the field and asks 'why?'. This is:","Defining a problem from an observation",["Ending an experiment","Writing a recipe","Painting"],"Questions start investigations.")
H('58.d.2.A',3,"A testable question in plant science is:","Does compost increase bean plant height?",["Are plants nice?","What is life?","Why do we eat?"],"Testable questions have measurable variables.")
H('58.d.2.B',3,"A fair experiment comparing two fertilizers on plants should:","Change only the fertilizer and keep other conditions equal",["Change many things","Use no plants","Skip measurements"],"Controls make comparisons valid.")
H('58.d.2.B',4,"Using several pots for each treatment helps to:","Reduce the effect of chance",["Hide data","Make it cheaper","Eliminate controls"],"Replication builds confidence.")
H('58.d.2.C',2,"Before a lab on soil chemistry, students should:","Review safety rules and wear protective gear",["Skip safety","Eat in lab","Taste samples"],"Safe habits prevent harm.")
H('58.d.2.C',3,"When diluting a strong acid for a soil test, add:","Acid slowly to water",["Water to acid quickly","Both at once","Nothing"],"Adding acid to water prevents splashing and heat spikes.")
H('58.d.2.D',2,"A microscope is used to:","Observe plant cells",["Measure soil temperature","Weigh seeds","Water plants"],"Microscopes magnify small structures.")
H('58.d.2.D',3,"A soil thermometer measures:","Soil temperature",["Moisture","pH","Texture"],"Temperature affects germination.")
H('58.d.2.E',2,"The SI unit for length is the:","Meter",["Foot","Pound","Quart"],"SI uses meters and centimeters.")
H('58.d.2.E',3,"Which is quantitative data from a plant experiment?","The seedling grew 4.5 centimeters",["The leaves look nice","It seems healthy","The plant is pretty"],"Quantitative data uses numbers.")
H('58.d.2.F',3,"A line graph of plant height over weeks shows:","How growth changes over time",["Plant names","Soil color","The pot price"],"Line graphs show trends.")
H('58.d.2.F',4,"A table of treatment averages helps to:","Compare groups at a glance",["Hide results","Remove data","Add confusion"],"Organized data supports analysis.")
H('58.d.2.G',3,"A diagram of the water cycle in a field is a(n):","Model of a system",["Real rainfall","Experiment","Fertilizer"],"Models represent processes.")
H('58.d.2.G',4,"A limit of a model of root growth is that it:","Simplifies the real, complex system",["Is perfectly accurate","Needs no testing","Matches every soil"],"Models leave out details.")
H('58.d.2.H',3,"A scientific hypothesis in plant science is:","A testable explanation or prediction",["A proven fact","A law","An opinion"],"Hypotheses are tested.")
H('58.d.2.H',4,"A scientific law, unlike a theory, usually:","Describes what happens under certain conditions",["Explains why in full","Is a guess","Cannot be tested"],"Laws describe patterns.")
H('58.d.3.A',3,"A greenhouse model is useful because it:","Lets students test plant responses to controlled conditions",["Replaces plants","Is exactly like fields","Needs no data"],"Models simplify variables.")
H('58.d.3.A',4,"A limitation of a small potted-plant model is:","It may not match field conditions",["It is always perfect","It cannot be repeated","It uses no soil"],"Scale limits generalization.")
H('58.d.3.B',3,"Looking at plant yield data, a student notices that most values cluster near 20 but one is 45. The 45 is a(n):","Outlier",["Mean","Median","Mode"],"Outliers differ greatly from others.")
H('58.d.3.B',4,"The mean of 10, 12, and 14 bushels is:","12",["10","14","36"],"Add and divide by three.")
H('58.d.3.C',3,"A field of 5 acres yields 40 bushels per acre. Total yield is:","200 bushels",["45 bushels","8 bushels","35 bushels"],"5 times 40 equals 200.")
H('58.d.3.C',4,"If soil sample A has pH 6 and B has pH 8, the difference is:","2 pH units",["14 units","1.3 units","48 units"],"8 minus 6 equals 2.")
H('58.d.3.D',3,"Evaluating a plant experiment includes checking if:","Variables were controlled and trials repeated",["The plants were pretty","The pots were new","The labels were colorful"],"Design quality affects trust.")
H('58.d.3.D',4,"An engineering design for a drip irrigation kit is judged by:","How well it meets goals within cost limits",["Its color","Its name","The packaging"],"Designs are tested against criteria.")

H('58.d.4.A',3,"Scientists support explanations of plant growth using:","Data and models",["Rumors","Opinions only","Hunches"],"Evidence supports claims.")
H('58.d.4.A',4,"A solution to nutrient runoff is stronger if it:","Is backed by test results",["Is untested","Is popular","Is cheap only"],"Data strengthen proposals.")
H('58.d.4.B',2,"Presenting soil test results to classmates is:","Communicating a scientific explanation",["Hiding data","Copying","Avoiding feedback"],"Sharing allows review.")
H('58.d.4.B',3,"A group communicating a soil study should:","Share data clearly and assign roles",["Read only a title","Omit data","Work apart"],"Clarity and teamwork matter.")
H('58.d.4.C',3,"Respectful scientific argument means:","Using evidence and listening to others",["Insults","Interrupting","Ignoring data"],"Focus on evidence.")
H('58.d.4.C',4,"If new data conflict with your claim about a fertilizer, you should:","Reconsider and revise your claim",["Hide it","Attack the data","Ignore it"],"Scientists update ideas.")
H('58.d.5.A',3,"Critiquing a crop study means:","Evaluating its design and conclusions",["Rejecting it","Copying it","Agreeing blindly"],"Critique is fair review.")
H('58.d.5.A',4,"A weakness in a plant study could be:","A very small sample with no controls",["Repeated trials","Clear methods","Good controls"],"Small samples reduce reliability.")
H('58.d.5.B',3,"Past soil science research has influenced thought by:","Improving understanding of erosion and fertility",["Stopping farming","Ending science","Removing soil"],"Research changes practice.")
H('58.d.5.B',4,"The Dust Bowl led to research on:","Soil conservation practices",["Space travel","Boat design","Fashion"],"Erosion drove new methods.")
H('58.d.5.C',2,"A resource for plant and soil science information is:","A university extension service",["A random post","A rumor","A meme"],"Extension offers research-based help.")
H('58.d.5.C',3,"Museums and libraries help students by:","Providing reliable references",["Selling soil","Hiding data","Closing early"],"Reliable sources aid research.")
H('58.d.6.A',3,"A student's plant science SAE should include:","A plan, goals, and an adult supervisor",["No plan","No goals","No records"],"SAEs are planned and supervised.")
H('58.d.6.A',4,"Growing and selling vegetables from a small plot is a type of:","Entrepreneurship SAE",["Placement only","Field trip","Exam"],"Owning a small business fits entrepreneurship.")
H('58.d.6.B',2,"Why record seed costs and sales in a crop project?","To calculate profit or loss",["To hide costs","To waste time","To lose data"],"Records measure outcomes.")
H('58.d.6.B',3,"A crop SAE record book includes:","Planting dates, inputs, and income",["Jokes","Movies","Nothing"],"Complete records support analysis.")
H('58.d.7.A',2,"Running for a chapter office helps develop:","Agricultural leadership",["Idleness","Isolation","Carelessness"],"Officers learn to lead.")
H('58.d.7.A',3,"Which opportunity builds leadership in plant and soil science?","Leading a soil judging practice for younger members",["Missing practice","Avoiding the group","Staying home"],"Leading peers builds skill.")
H('58.d.7.B',2,"A program of activities helps the chapter to:","Plan events and goals for the year",["Cancel meetings","Hide the budget","Close down"],"It organizes the year.")
H('58.d.7.B',3,"Helping at the chapter's tree planting is:","Participating in the local program of activities",["Breaking rules","Avoiding service","Quitting"],"Taking part supports goals.")
H('58.d.7.C',3,"Documenting experience in plant and soil science may show:","Skills learned and hours worked",["Nothing","Unrelated hobbies","Only grades"],"Records support applications.")
H('58.d.7.C',4,"Updating experience records each semester ensures:","Accuracy for jobs and scholarships",["Errors","Loss of details","Delays"],"Current records help.")

H('58.d.8.A',3,"The domestication of wheat and barley was a major milestone because it:","Allowed people to settle and farm",["Ended farming","Created cities overnight","Stopped migration"],"Farming enabled settled societies.")
H('58.d.8.A',4,"The Columbian Exchange moved crops such as:","Potatoes, corn, and tomatoes between continents",["Only wheat","Only rice","Only grapes"],"Global exchange changed diets.")
H('58.d.8.B',3,"Humans have influenced plant selection by:","Saving seeds from the best plants",["Burning crops","Ignoring traits","Planting weeds"],"Selective breeding changes crops.")
H('58.d.8.B',4,"Over many generations, selecting large-seeded plants results in:","Crops with larger seeds",["Smaller seeds","No change","Extinct plants"],"Selection shapes traits.")
H('58.d.8.C',3,"Early civilizations often settled on river valleys with:","Fertile, easily worked soils",["Rocky cliffs","Deserts","Ice"],"Good soil supported farming.")
H('58.d.8.C',4,"Soil that is depleted by overuse can lead to:","Decline of farming societies",["Larger harvests","Lower population needs","More forests"],"Soil health affects survival.")
H('58.d.8.D',3,"Cotton shaped the early economy of the American South by:","Becoming a major cash crop",["Being unused","Being banned","Being a minor crop"],"Cotton drove trade and labor systems.")
H('58.d.8.D',4,"Plants shape world economies when crops like coffee or sugar:","Are traded globally",["Are never traded","Cannot grow","Are ignored"],"Trade makes crops economic drivers.")

H('58.d.9.A',3,"The organelle in plant cells that carries out photosynthesis is the:","Chloroplast",["Nucleus","Vacuole","Mitochondrion"],"Chloroplasts capture light.")
H('58.d.9.A',4,"Plant cell walls are made mainly of:","Cellulose",["Protein","Fat","Glass"],"Cellulose provides structure.")
H('58.d.9.B',3,"Mitosis in plant roots produces:","New cells for growth",["Gametes","Seeds","Flowers"],"Mitosis builds tissue.")
H('58.d.9.B',4,"Cell division in plants occurs fastest in:","Meristems",["Mature leaves","Bark","Dead wood"],"Meristems are growth zones.")
H('58.d.9.C',3,"Root cells differ from leaf cells because roots:","Have root hairs for absorption",["Have chloroplasts","Carry out photosynthesis","Produce flowers"],"Structure fits function.")
H('58.d.9.C',4,"Guard cells in leaves control:","Opening and closing of stomata",["Root growth","Flower color","Seed size"],"Guard cells regulate gas exchange.")
H('58.d.9.D',3,"The correct order from smaller to larger is:","Cell, tissue, organ, organism",["Organ, cell, tissue, organism","Organism, cell, organ, tissue","Tissue, organism, cell, organ"],"Organization builds complexity.")
H('58.d.9.D',4,"A leaf is an example of a(n):","Organ",["Cell","Tissue","Molecule"],"Leaves are organs made of tissues.")

H('58.d.10.A',3,"The main function of roots is to:","Absorb water and nutrients and anchor the plant",["Make food","Produce seeds","Make pollen"],"Roots support and feed the plant.")
H('58.d.10.A',4,"Leaves are the site of:","Photosynthesis",["Pollination","Rooting","Seed dispersal"],"Leaves make sugars.")
H('58.d.10.B',3,"A monocot stem usually has vascular bundles that are:","Scattered",["In a ring","Absent","In the roots only"],"Monocot bundles are scattered.")
H('58.d.10.B',4,"A dicot root often has a:","Taproot",["Fibrous root only","No roots","Aerial root"],"Dicots often have taproots.")
H('58.d.10.C',3,"Propagating a plant by cuttings is a(n):","Asexual method",["Sexual method","Seed method","Pollination method"],"Cuttings clone the parent.")
H('58.d.10.C',4,"Propagation by seed produces plants that:","May vary from the parent",["Are identical clones","Are sterile","Never grow"],"Seeds combine genes.")
H('58.d.10.D',3,"A potato is a modified:","Stem called a tuber",["Root","Leaf","Flower"],"Tubers store food.")
H('58.d.10.D',4,"A rhizome, such as in ginger or bamboo, is a:","Horizontal underground stem",["Vertical root","Leaf","Flower"],"Rhizomes spread plants.")

H('58.d.11.A',3,"Photosynthesis uses light, water, and carbon dioxide to make:","Glucose and oxygen",["Water and CO2","Salt","Protein only"],"Photosynthesis stores energy in sugar.")
H('58.d.11.A',4,"Cellular respiration in plants:","Releases energy from sugars",["Makes sugar from light","Absorbs water","Makes seeds"],"Respiration powers cells.")
H('58.d.11.B',3,"Mineral nutrients come from plants' uptake of:","Dissolved ions in soil water",["Air only","Light only","Sound"],"Roots absorb ions.")
H('58.d.11.B',4,"Without adequate nitrogen, leaves typically:","Turn pale green or yellow",["Turn red","Grow larger","Produce flowers"],"Nitrogen is needed for chlorophyll.")
H('58.d.11.C',3,"Which three nutrients are most often limiting in soil?","Nitrogen, phosphorus, and potassium",["Gold, silver, copper","Carbon, oxygen, water","Sodium, helium, neon"],"N, P and K are primary nutrients.")
H('58.d.11.C',4,"A soil test measures nutrients to help determine:","Fertilizer needs",["Rainfall","Planting date","Seed price"],"Tests guide fertilization.")
H('58.d.11.D',3,"A macronutrient is one that plants need:","In relatively large amounts",["In tiny amounts","Not at all","Only in winter"],"Macronutrients include N, P, K.")
H('58.d.11.D',4,"Iron and zinc are examples of:","Micronutrients",["Macronutrients","Fertilizers only","Pesticides"],"They are needed in small amounts.")

H('58.d.12.A',3,"Soil forms from the breakdown of:","Parent material over time",["Water only","Wind only","Plastic"],"Weathering creates soil.")
H('58.d.12.A',4,"Which factor helps soil form?","Climate, organisms, and time",["Only color","Only money","Only fertilizer"],"Soil forms through many factors.")
H('58.d.12.B',3,"Soil texture is determined by the proportions of:","Sand, silt, and clay",["Water, air, rock","Humus, gold, sand","Salt, sugar, fat"],"Texture classes use particle sizes.")
H('58.d.12.B',4,"A soil that feels gritty and drains quickly is high in:","Sand",["Clay","Silt","Humus"],"Sand is coarse.")
H('58.d.12.C',3,"Mollisols are soils known for being:","Dark and fertile, formed under grass",["Frozen","Sandy only","Organic wetlands"],"Mollisols are productive grassland soils.")
H('58.d.12.C',4,"Soil orders are classified based on:","Properties such as horizons and formation",["Color names","Prices","Owner names"],"Taxonomy uses properties.")
H('58.d.12.D',3,"Crop rotation conserves soil by:","Alternating crops to reduce nutrient depletion and pests",["Planting the same crop","Leaving bare ground","Burning fields"],"Rotation maintains fertility.")
H('58.d.12.D',4,"Contour farming reduces erosion by:","Planting along slope contours",["Plowing up and down","Removing plants","Leaving soil bare"],"Contours slow runoff.")
H('58.d.12.E',3,"Soil mechanics matters for buildings because it affects:","Foundation stability",["Paint color","Roof shape","Window size"],"Soil bearing capacity matters.")
H('58.d.12.E',4,"Expansive clay soils can damage foundations by:","Swelling when wet and shrinking when dry",["Staying the same","Draining fast","Freezing"],"Volume change cracks structures.")
H('58.d.12.F',3,"A tillage trial compares:","Different tillage methods on crop and soil",["Seeds only","Paint colors","Brands"],"Trials show effects.")
H('58.d.12.F',4,"No-till farming helps soil by:","Leaving residue to protect the surface",["Increasing erosion","Exposing soil","Burning residue"],"Residue shields soil.")
H('58.d.12.G',3,"A soil judging activity may ask students to:","Describe horizons and evaluate land use",["Paint the soil","Count cars","Taste samples"],"Soil evaluation builds skills.")
H('58.d.12.G',4,"Reading a soil pit helps students identify:","Layers called horizons",["Types of cars","Brands","Rainfall"],"Horizons reveal soil history.")
H('58.d.12.H',3,"Soil health can be evaluated through:","Soil testing for nutrients, pH, and organic matter",["Counting stones","Guessing","Watching clouds"],"Tests quantify health.")
H('58.d.12.H',4,"A pH below 5.5 suggests soil is:","Strongly acidic",["Neutral","Alkaline","Salty"],"Low pH means acidity.")
H('58.d.12.I',3,"Soil ecology studies the relationships among:","Soil organisms and their environment",["Cars and roads","Fertilizer brands","Weather maps"],"Organisms drive nutrient cycles.")
H('58.d.12.I',4,"Earthworms improve soil by:","Aerating it and mixing organic matter",["Removing nutrients","Compacting soil","Killing plants"],"Worms improve structure.")

H('58.d.13.A',3,"Weathering contributes to soil formation by:","Breaking rock into smaller pieces",["Making rock larger","Stopping soil","Adding plastic"],"Weathering creates parent material.")
H('58.d.13.A',4,"Rock broken down over thousands of years becomes:","Parent material for soil",["Water","Plant seeds","Fertilizer"],"Weathering produces mineral particles.")
H('58.d.13.B',3,"Frost wedging is an example of:","Mechanical weathering",["Chemical weathering","Biological growth","Soil mixing"],"Freezing water cracks rock.")
H('58.d.13.B',4,"Acid rain dissolving limestone is:","Chemical weathering",["Mechanical weathering","Erosion only","Deposition"],"Chemical reactions alter minerals.")
H('58.d.13.C',3,"Canyons result from:","Long-term erosion by water",["Short rain","Soil mixing","Wind in a day"],"Rivers carve rock over time.")
H('58.d.13.C',4,"Sand dunes form when wind:","Deposits sand",["Dissolves rock","Freezes water","Plants seeds"],"Wind moves and drops sand.")
H('58.d.13.D',3,"Plant roots contribute to soil formation by:","Breaking rock and adding organic matter",["Making rocks","Removing nutrients","Stopping decay"],"Roots and litter build soil.")
H('58.d.13.D',4,"Lichens help start soil formation on bare rock by:","Slowly breaking it down",["Making it harder","Adding sand","Stopping weathering"],"Lichens are pioneer species.")

H('58.d.14.A',3,"A group of the same species living in an area is a:","Population",["Community","Biome","Ecosystem"],"Population is one species in a place.")
H('58.d.14.A',4,"All living and nonliving things interacting in an area form an:","Ecosystem",["Population","Species","Cell"],"Ecosystems include biotic and abiotic parts.")
H('58.d.14.B',3,"A plant that is native to a region:","Evolved there naturally",["Was recently imported","Is always invasive","Does not exist"],"Natives belong to the ecosystem.")
H('58.d.14.B',4,"An introduced plant that spreads aggressively is called:","Invasive",["Native","Endemic","Extinct"],"Invasives harm ecosystems.")
H('58.d.14.C',3,"Native Texas plants are often better at surviving:","Local droughts with less water",["Any climate","Cold only","Tropics only"],"Adaptation to local conditions.")
H('58.d.14.C',4,"Introduced plants may compete with natives for:","Light, water, and nutrients",["Nothing","Homes","Phones"],"Competition affects diversity.")
H('58.d.14.D',3,"The water cycle is an example of an:","Abiotic cycle",["Biotic cycle","Food chain","Population"],"Abiotic cycles involve nonliving factors.")
H('58.d.14.D',4,"A student recording rainfall and plant growth over months is:","Compiling data about environmental fluctuations",["Ignoring data","Making a game","Writing a story"],"Data show relationships.")
H('58.d.14.E',3,"A prolonged drought can cause:","Plant stress and reduced growth in local ecosystems",["More growth","More rain","Larger harvests"],"Drought limits production.")
H('58.d.14.E',4,"Changes in rainfall patterns can shift:","Which plants thrive in an area",["The shape of the sun","The seasons themselves","Gravity"],"Climate shapes communities.")
H('58.d.14.F',3,"An example of human activity with a negative impact on ecosystems is:","Overgrazing that strips vegetation",["Planting native trees","Restoring wetlands","Using cover crops"],"Overgrazing causes erosion.")
H('58.d.14.F',4,"A positive human impact on land is:","Restoring native grasses",["Clearing all vegetation","Dumping waste","Draining wetlands"],"Restoration helps ecosystems.")

H('58.d.15.A',3,"Modern corn evolved from a wild grass called:","Teosinte",["Wheat","Rye","Oats"],"Corn was domesticated from teosinte.")
H('58.d.15.A',4,"Genetic variation in crops is important because it:","Allows adaptation and breeding for new traits",["Prevents breeding","Reduces yields always","Stops evolution"],"Diversity is breeding material.")
H('58.d.15.B',3,"Classifying plants using taxonomy begins with the broadest group, the:","Kingdom",["Species","Genus","Family"],"Taxonomy runs from kingdom to species.")
H('58.d.15.B',4,"The scientific name of a plant has two parts: genus and:","Species",["Order","Class","Phylum"],"Binomial nomenclature.")
H('58.d.15.C',3,"A high-quality seed lot is one with:","High germination and purity",["Weeds and broken seeds","Moldy seed","Mixed species"],"Seed quality affects stands.")
H('58.d.15.C',4,"A germination test reports the:","Percent of seeds that sprout",["Weight","Seed price","Plant height"],"Germination percent guides seeding rate.")
H('58.d.15.D',3,"A student might use a microscope to identify:","Fungal spores or insect parts on plant tissue",["Soil color","Pot price","Rainfall"],"Lab tools help diagnose.")
H('58.d.15.D',4,"A hand lens helps in the field to:","Examine small pests on leaves",["Measure rainfall","Test soil pH","Count seeds"],"Magnification reveals tiny insects.")
H('58.d.15.E',3,"Evaluating plant management practices includes comparing:","Yields and costs under different practices",["Names","Colors","Brands"],"Evaluation uses outcomes.")
H('58.d.15.E',4,"Genetically improved seed may be evaluated for:","Yield, disease resistance, and cost",["Label color","Bag size","Slogans"],"Traits and economics matter.")
H('58.d.15.F',3,"Local Texas crop trends are tracked by:","Agencies such as the Texas A&M AgriLife Extension",["Social posts","Gossip","Fashion magazines"],"Extension publishes crop data.")
H('58.d.15.F',4,"Changes in the acreage of cotton versus grain sorghum over years shows:","Trends in crop varieties and species grown",["Nothing","Weather only","Soil color"],"Trends guide planning.")
H('58.d.15.G',3,"A recent advancement in plant science is:","Drought-tolerant crop varieties",["Hand plows","Sundials","Candles"],"Improved varieties help production.")
H('58.d.15.G',4,"Remote sensing and soil sensors are advancements that help to:","Monitor crops and soil conditions",["Replace plants","Stop science","Slow research"],"Technology gives data.")

H('58.d.16.A',3,"Land use planning aims to:","Balance production with conservation",["Ignore the land","Maximize waste","Eliminate farming"],"Planning helps sustain land.")
H('58.d.16.A',4,"Terracing on steep farmland is a method of:","Land management that reduces erosion",["Cutting forests","Draining lakes","Leaving fields bare"],"Terraces slow runoff.")
H('58.d.16.B',3,"Sources of water for plant production include:","Rainfall, wells, and rivers",["Only dew","Only snow","Only fog"],"Water sources vary.")
H('58.d.16.B',4,"Salty irrigation water can harm crops by:","Reducing water uptake and damaging roots",["Boosting growth","Adding nutrients","Improving soil"],"Salt stress limits plants.")
H('58.d.16.C',3,"Rainwater collection is a conservation practice that:","Captures water for later use",["Wastes water","Pollutes soil","Increases runoff"],"Harvesting rain saves resources.")
H('58.d.16.C',4,"Mulching conserves water by:","Reducing evaporation from the soil surface",["Increasing evaporation","Adding salt","Blocking rain"],"Mulch shades soil.")
H('58.d.16.D',3,"The economy of Texas depends on agriculture because it:","Provides food, fiber, and jobs",["Has no value","Is tiny","Is unrelated"],"Agriculture is a major industry.")
H('58.d.16.D',4,"Healthy soil supports agriculture and also:","Water quality and ecosystems",["Nothing else","Only roads","Only buildings"],"Soil links many systems.")
H('58.d.16.E',3,"A debate on irrigation technology might weigh:","Water saved versus cost of installation",["Colors","Names","Shapes"],"Debates weigh benefits and costs.")
H('58.d.16.E',4,"Overuse of fertilizer can harm water quality by causing:","Nutrient runoff and algae growth",["Cleaner water","More fish","Less algae"],"Excess nutrients cause eutrophication.")
H('58.d.16.F',3,"A flood can damage soil by:","Washing away topsoil",["Adding topsoil","Adding crops","Removing weeds only"],"Floods erode land.")
H('58.d.16.F',4,"After a wildfire, soil is more vulnerable to:","Erosion and runoff",["Higher fertility","Better drainage","Thicker cover"],"Burned ground lacks cover.")
H('58.d.16.G',3,"Deforestation in one region may affect other regions by:","Changing rainfall and carbon levels",["Having no effect","Only helping locals","Stopping the wind"],"Environmental changes can be global.")
H('58.d.16.G',4,"Regional soil loss can affect global food supply by:","Reducing crop production",["Increasing it always","Having no effect","Replacing food"],"Soil underpins food systems.")

H('58.d.17.A',3,"A watershed is the land area that:","Drains to a common stream or river",["Never drains","Has no water","Is always flat"],"Watersheds collect runoff.")
H('58.d.17.A',4,"Characteristics of a local watershed include:","Land use, slope, and stream flow",["Phone numbers","Brand names","Paint colors"],"They describe how water moves.")
H('58.d.17.B',3,"Urbanization increases flooding because pavement:","Prevents water from soaking in",["Absorbs water","Grows plants","Cools the soil"],"Impervious surfaces raise runoff.")
H('58.d.17.B',4,"A drought can lower stream flow and:","Stress irrigation supplies",["Increase aquifers","Raise water quality","Cool the water"],"Dry spells limit water.")

H('58.d.18.A',3,"Soil and plants are interrelated because plants:","Stabilize soil and add organic matter",["Remove all soil","Never need soil","Create rocks"],"Plants protect and build soil.")
H('58.d.18.A',4,"Soil supports plants by providing:","Anchorage, water, air, and nutrients",["Only light","Only heat","Only sound"],"Soil meets plant needs.")
H('58.d.18.B',3,"Compared with agricultural soils, urban soils are often:","Compacted and disturbed",["Deeper and richer","Always fertile","Untouched"],"Construction compacts soil.")
H('58.d.18.B',4,"Urban soils often have lower organic matter because of:","Removal of topsoil during development",["More worms","Extra compost","Natural forests"],"Development strips topsoil.")
H('58.d.18.C',3,"Hydroponics is growing plants in:","Nutrient solution instead of soil",["Pure sand","Dry air","Dirt only"],"Roots sit in solution.")
H('58.d.18.C',4,"In a hydroponic system the solution must be monitored for:","Nutrient concentration and pH",["Sunset times","Color","Brand"],"Control of the solution is critical.")
H('58.d.18.D',3,"An advantage of hydroponics is that it:","Uses less water and allows controlled nutrition",["Uses more water","Needs no light","Is always free"],"Efficient resource use.")
H('58.d.18.D',4,"A disadvantage of hydroponics is that it:","Can have high startup costs and needs close monitoring",["Never fails","Costs nothing","Needs no care"],"Systems need investment.")

H('58.d.19.A',3,"Cotton in Texas begins its life cycle with:","Planting seed in warm soil",["Harvest","Drying","Ginning"],"Planting starts the cycle.")
H('58.d.19.A',4,"A major Texas crop that thrives in the High Plains with irrigation is:","Cotton",["Cranberries","Maple","Cocoa"],"The High Plains grows lots of cotton.")
H('58.d.19.B',3,"Plant breeding uses genetics to:","Select plants with desired traits as parents",["Remove genes","Ignore traits","Stop evolution"],"Breeding combines traits.")
H('58.d.19.B',4,"Crossing a high-yield plant with a disease-resistant plant aims to produce:","Offspring with both traits",["Weaker plants","No seeds","Identical clones"],"Breeders combine desirable traits.")
H('58.d.19.C',3,"A new crop variety that took many years of selection and testing shows:","Plant breeding takes time",["Instant results","Luck","No testing"],"Development is slow.")
H('58.d.19.C',4,"Field trials of new varieties help breeders to:","Compare performance across locations",["Skip testing","Reduce data","Avoid farmers"],"Trials give evidence.")
H('58.d.19.D',3,"A student testing inheritance of flower color in peas would:","Cross parents and count offspring phenotypes",["Guess","Paint flowers","Skip counting"],"Experiments test genetics.")
H('58.d.19.D',4,"A ratio of about 3 purple to 1 white offspring from two hybrid parents supports:","Dominant and recessive inheritance",["Blending","No genetics","Mutation only"],"3:1 is Mendelian.")
H('58.d.19.E',3,"An alternative growing method such as aquaponics combines:","Fish and plant production",["Cattle and wheat","Trees and sand","Soil and rock"],"Fish waste feeds plants.")
H('58.d.19.E',4,"Testing a hydroponic lettuce system against soil-grown lettuce compares:","Growth rate, water use, and yield",["Pot colors","Names","Slogans"],"Fair tests compare results.")

H('56.d.3.A',3,"A chapter member who chairs a committee for a vineyard field day is developing:","Leadership and organizing skills",["Spectator habits","Fewer duties","Weaker teamwork"],"Chairing builds leadership.")
H('57.d.3.A',2,"Which action shows leadership in an advanced floral class?","Coordinating teammates on a large event order",["Avoiding group tasks","Leaving early","Ignoring deadlines"],"Coordinating others builds leadership.")
